import urllib.request,re,concurrent.futures
urls=['https://gschool.ecust.edu.cn/2026/0916/c12748a193439/page.htm','https://gschool.ecust.edu.cn/2026/0916/c12748a193440/page.htm','https://cce.upc.edu.cn/qbwtz/list1.htm','https://cmse.buct.edu.cn/4117/list.htm']
def get(u):
 try:
  s=urllib.request.urlopen(u,timeout=20).read().decode('utf-8','replace')
  matches=re.findall(r'.{0,150}(?:\\.pdf|2027|2026年接收推荐).{0,180}',s)
  return u,matches[:30]
 except Exception as e:return u,str(e)
for u,r in concurrent.futures.ThreadPoolExecutor().map(get,urls):
 print(u);print('\\n'.join(r) if isinstance(r,list) else r)
